 var calMemoryCalendarClassID = Components.ID("{bda0dd7f-0a2f-4fcf-ba08-5517e6fbf133}");
 var calMemoryCalendarInterfaces = [
-  "calICalendar",
+  "Ci.calICalendar",
   "calISchedulingSupport",
   "calIOfflineStorage",
   "calISyncWriteCalendar",
